INSERT INTO security_tips (title, description, created_at) VALUES
  ('Enable Two-Factor Authentication', 'Turn on 2FA for email, banking and social media. Even if a phisher steals your password, they cannot log in without the second factor (an authenticator app is safer than SMS).', NOW() - INTERVAL 8 DAY),
  ('Check the domain, not the logo', 'Logos and page designs are easy to copy. Always read the full domain in the address bar – \"paypal.com.secure-login.xyz\" is NOT PayPal.', NOW() - INTERVAL 7 DAY),
  ('HTTPS is not a safety guarantee', 'The padlock only means the connection is encrypted. Phishing sites can get free HTTPS certificates too, so always verify the domain itself.', NOW() - INTERVAL 6 DAY),
  ('Never share OTP codes', 'Banks and services will never ask you for your one-time password (OTP) by phone, SMS or email. Anyone asking for it is trying to take over your account.', NOW() - INTERVAL 5 DAY),
  ('Use a password manager', 'A password manager creates unique passwords for every site and will not auto-fill your login on a fake look-alike domain – an extra phishing warning.', NOW() - INTERVAL 4 DAY),
  ('Hover before you click', 'On a computer, hover over a link to see its real destination. On mobile, long-press the link. If the address looks strange, do not open it.', NOW() - INTERVAL 3 DAY),
  ('Keep software updated', 'Install operating system, browser and app updates promptly. Many malware attacks exploit old vulnerabilities that already have fixes.', NOW() - INTERVAL 2 DAY),
  ('Back up your important files', 'Keep regular offline or cloud backups. If ransomware encrypts your files, a recent backup lets you recover without paying criminals.', NOW() - INTERVAL 1 DAY);
