  (2, 'http://paypa1.com/login/verify', 62, 'HIGH RISK', '{\"normalizedUrl\":\"http://paypa1.com/login/verify\",\"domain\":\"paypa1.com\",\"registeredDomain\":\"paypa1.com\",\"summary\":\"3 warning sign(s) were found, giving a risk score of 62/100.\",\"indicators\":[{\"id\":\"no_https\",\"category\":\"HTTPS\",\"points\":15,\"severity\":\"medium\",\"title\":\"No HTTPS encryption\",\"description\":\"The link uses plain HTTP. Any data you send (like passwords) could be intercepted.\"},{\"id\":\"keywords\",\"category\":\"Keywords\",\"points\":12,\"severity\":\"medium\",\"title\":\"Suspicious keywords\",\"description\":\"The URL contains sensitive words: login, verify. Phishing links often use words like \\\"login\\\" or \\\"verify\\\" to create trust or urgency.\"},{\"id\":\"impersonation\",\"category\":\"Impersonation\",\"points\":35,\"severity\":\"high\",\"title\":\"Look-alike (typosquatting) domain\",\"description\":\"\\\"paypa1.com\\\" imitates \\\"paypal\\\" by swapping look-alike characters (such as 1 for l or 0 for o). The real site is paypal.com.\"}],\"checks\":[{\"name\":\"HTTPS availability\",\"passed\":false,\"detail\":\"HTTPS not used or not confirmed\"},{\"name\":\"IP address instead of domain\",\"passed\":true,\"detail\":\"Uses a domain name\"},{\"name\":\"URL length\",\"passed\":true,\"detail\":\"30 characters\"},{\"name\":\"Suspicious symbols & characters\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Suspicious domain name\",\"passed\":true,\"detail\":\"Registered domain: paypa1.com\"},{\"name\":\"URL shortening service\",\"passed\":true,\"detail\":\"Not a known shortener\"},{\"name\":\"Suspicious keywords\",\"passed\":false,\"detail\":\"login, verify\"},{\"name\":\"Domain impersonation\",\"passed\":false,\"detail\":\"Look-alike (typosquatting) domain\"}],\"recommendations\":[\"Do NOT open this link or enter any information on this website.\",\"If you already entered a password on this site, change it immediately and enable two-factor authenti