  (2, 'http://192.168.10.5/account/update.php', 52, 'SUSPICIOUS', '{\"normalizedUrl\":\"http://192.168.10.5/account/update.php\",\"domain\":\"192.168.10.5\",\"registeredDomain\":\"10.5\",\"summary\":\"3 warning sign(s) were found, giving a risk score of 52/100.\",\"indicators\":[{\"id\":\"no_https\",\"category\":\"HTTPS\",\"points\":15,\"severity\":\"medium\",\"title\":\"No HTTPS encryption\",\"description\":\"The link uses plain HTTP. Any data you send (like passwords) could be intercepted.\"},{\"id\":\"ip_host\",\"category\":\"Domain\",\"points\":25,\"severity\":\"high\",\"title\":\"IP address used instead of domain name\",\"description\":\"The link points to the raw IP address 192.168.10.5. Legitimate services almost always use a domain name.\"},{\"id\":\"keywords\",\"category\":\"Keywords\",\"points\":12,\"severity\":\"medium\",\"title\":\"Suspicious keywords\",\"description\":\"The URL contains sensitive words: account, update. Phishing links often use words like \\\"login\\\" or \\\"verify\\\" to create trust or urgency.\"}],\"checks\":[{\"name\":\"HTTPS availability\",\"passed\":false,\"detail\":\"HTTPS not used or not confirmed\"},{\"name\":\"IP address instead of domain\",\"passed\":false,\"detail\":\"192.168.10.5\"},{\"name\":\"URL length\",\"passed\":true,\"detail\":\"38 characters\"},{\"name\":\"Suspicious symbols & characters\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Suspicious domain name\",\"passed\":true,\"detail\":\"Registered domain: 10.5\"},{\"name\":\"URL shortening service\",\"passed\":true,\"detail\":\"Not a known shortener\"},{\"name\":\"Suspicious keywords\",\"passed\":false,\"detail\":\"account, update\"},{\"name\":\"Domain impersonation\",\"passed\":true,\"detail\":\"No known brand imitation detected\"}],\"recommendations\":[\"Avoid entering passwords, card numbers, or personal details on this site.\",\"Visit the organisation\'s website by typing its official address yourself instead of clicking the link.\",\"The connection i