  (4, 'https://accounts.google.com.security-check.top/signin', 70, 'HIGH RISK', '{\"normalizedUrl\":\"https://accounts.google.com.security-check.top/signin\",\"domain\":\"accounts.google.com.security-check.top\",\"registeredDomain\":\"security-check.top\",\"summary\":\"4 warning sign(s) were found, giving a risk score of 70/100.\",\"indicators\":[{\"id\":\"https_present\",\"category\":\"HTTPS\",\"points\":0,\"severity\":\"info\",\"title\":\"Uses HTTPS\",\"description\":\"The link uses HTTPS, so traffic is encrypted. However, HTTPS does NOT prove a website is legitimate – many phishing sites use free HTTPS certificates.\"},{\"id\":\"many_subdomains\",\"category\":\"Domain\",\"points\":12,\"severity\":\"medium\",\"title\":\"Too many subdomains\",\"description\":\"The address has 3 subdomain levels (accounts.google.com.security-check.top). This is often used to push the real domain out of view.\"},{\"id\":\"suspicious_tld\",\"category\":\"Domain\",\"points\":10,\"severity\":\"medium\",\"title\":\"High-risk domain ending \\\".top\\\"\",\"description\":\"\\\".top\\\" domains are cheap and frequently abused in phishing campaigns. This alone does not mean the site is malicious.\"},{\"id\":\"keywords\",\"category\":\"Keywords\",\"points\":18,\"severity\":\"medium\",\"title\":\"Suspicious keywords\",\"description\":\"The URL contains sensitive words: signin, account, security. Phishing links often use words like \\\"login\\\" or \\\"verify\\\" to create trust or urgency.\"},{\"id\":\"impersonation\",\"category\":\"Impersonation\",\"points\":30,\"severity\":\"high\",\"title\":\"Possible brand impersonation in domain\",\"description\":\"The domain contains \\\"google\\\" but is not an official google domain (google.com). Attackers often put trusted brand names into fake domains.\"}],\"checks\":[{\"name\":\"HTTPS availability\",\"passed\":true,\"detail\":\"HTTPS used (encryption only, not proof of safety)\"},{\"name\":\"IP address instead of domain\",\"passed\":true,\"detail\":