  (2, 'https://amazon.com@evil-shop.ru/', 60, 'HIGH RISK', '{\"normalizedUrl\":\"https://amazon.com@evil-shop.ru/\",\"domain\":\"evil-shop.ru\",\"registeredDomain\":\"evil-shop.ru\",\"summary\":\"2 warning sign(s) were found, giving a risk score of 60/100.\",\"indicators\":[{\"id\":\"https_present\",\"category\":\"HTTPS\",\"points\":0,\"severity\":\"info\",\"title\":\"Uses HTTPS\",\"description\":\"The link uses HTTPS, so traffic is encrypted. However, HTTPS does NOT prove a website is legitimate – many phishing sites use free HTTPS certificates.\"},{\"id\":\"at_symbol\",\"category\":\"Symbols\",\"points\":30,\"severity\":\"high\",\"title\":\"\\\"@\\\" symbol in URL\",\"description\":\"Browsers ignore everything before \\\"@\\\" in a URL, so this link really opens \\\"evil-shop.ru\\\", not what appears before the \\\"@\\\".\"},{\"id\":\"impersonation\",\"category\":\"Impersonation\",\"points\":30,\"severity\":\"high\",\"title\":\"Brand name disguised before \\\"@\\\"\",\"description\":\"The link shows \\\"amazon.com\\\" before the \\\"@\\\" to look like amazon, but actually opens \\\"evil-shop.ru\\\".\"}],\"checks\":[{\"name\":\"HTTPS availability\",\"passed\":true,\"detail\":\"HTTPS used (encryption only, not proof of safety)\"},{\"name\":\"IP address instead of domain\",\"passed\":true,\"detail\":\"Uses a domain name\"},{\"name\":\"URL length\",\"passed\":true,\"detail\":\"32 characters\"},{\"name\":\"Suspicious symbols & characters\",\"passed\":false,\"detail\":\"1 issue(s) found\"},{\"name\":\"Suspicious domain name\",\"passed\":true,\"detail\":\"Registered domain: evil-shop.ru\"},{\"name\":\"URL shortening service\",\"passed\":true,\"detail\":\"Not a known shortener\"},{\"name\":\"Suspicious keywords\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Domain impersonation\",\"passed\":false,\"detail\":\"Brand name disguised before \\\"@\\\"\"}],\"recommendations\":[\"Do NOT open this link or enter any information on this website.\",\"If you already entered a password on this site, change it immediately and enable two-factor authentication (2FA).\",\"Report the link to your IT/security team or the impersonated organisation.\",\"Remember: HTTPS only encrypts the connection. Phishing sites can also use HTTPS.\",\"Check the domain letter by letter – compare it with the official domain of the brand.\",\"Keep your browser and antivirus up to date and use a password manager (it won\'t auto-fill on fake domains).\"],\"disclaimer\":\"This result comes from transparent, rule-based automated analysis. It cannot guarantee that a website or email is safe or malicious. Always verify through official channels before sharing information.\",\"method\":\"Rule-based analysis (no AI / machine learning). The link was not opened.\"}', NOW() - INTERVAL 3 DAY - INTERVAL 10 HOUR),
  (2, 'http://netflix-billing-update.online/account/payment', 83, 'HIGH RISK', '{\"normalizedUrl\":\"http://netflix-billing-update.online/account/payment\",\"domain\":\"netflix-billing-update.online\",\"registeredDomain\":\"netflix-billing-update.online\",\"summary\":\"5 warning sign(s) were found, giving a risk score of 83/100.\",\"indicators\":[{\"id\":\"no_https\",\"category\":\"HTTPS\",\"points\":15,\"severity\":\"medium\",\"title\":\"No HTTPS encryption\",\"description\":\"The link uses plain HTTP. Any data you send (like passwords) could be intercepted.\"},{\"id\":\"many_hyphens\",\"category\":\"Symbols\",\"points\":10,\"severity\":\"medium\",\"title\":\"Many hyphens in domain\",\"description\":\"The domain \\\"netflix-billing-update.online\\\" has 2 hyphens. Phishing domains often look like \\\"secure-login-update.com\\\".\"},{\"id\":\"suspicious_tld\",\"category\":\"Domain\",\"points\":10,\"severity\":\"medium\",\"title\":\"High-risk domain ending \\\".online\\\"\",\"description\":\"\\\".online\\\" domains are cheap and frequently abused in phishing campaigns. This alone does not mean the site is malicious.\"},{\"id\":\"keywords\",\"category\":\"Keywords\",\"points\":18,\"severity\":\"medium\",\"title\":\"Suspicious keywords\",\"description\":\"The URL contains sensitive words: account, update, billing. Phishing links often use words like \\\"login\\\" or \\\"verify\\\" to create trust or urgency.\"},{\"id\":\"impersonation\",\"category\":\"Impersonation\",\"points\":30,\"severity\":\"high\",\"title\":\"Possible brand impersonation in domain\",\"description\":\"The domain contains \\\"netflix\\\" but is not an official netflix domain (netflix.com). Attackers often put trusted brand names into fake domains.\"}],\"checks\":[{\"name\":\"HTTPS availability\",\"passed\":false,\"detail\":\"HTTPS not used or not confirmed\"},{\"name\":\"IP address instead of domain\",\"passed\":true,\"detail\":\"Uses a domain name\"},{\"name\":\"URL length\",\"passed\":true,\"detai