  (3, 'https://www.microsoft.com/en-us/security', 6, 'SAFE', '{\"normalizedUrl\":\"https://www.microsoft.com/en-us/security\",\"domain\":\"www.microsoft.com\",\"registeredDomain\":\"microsoft.com\",\"summary\":\"1 warning sign(s) were found, giving a risk score of 6/100.\",\"indicators\":[{\"id\":\"https_present\",\"category\":\"HTTPS\",\"points\":0,\"severity\":\"info\",\"title\":\"Uses HTTPS\",\"description\":\"The link uses HTTPS, so traffic is encrypted. However, HTTPS does NOT prove a website is legitimate – many phishing sites use free HTTPS certificates.\"},{\"id\":\"keywords\",\"category\":\"Keywords\",\"points\":6,\"severity\":\"low\",\"title\":\"Suspicious keywords\",\"description\":\"The URL contains sensitive words: security. Phishing links often use words like \\\"login\\\" or \\\"verify\\\" to create trust or urgency.\"}],\"checks\":[{\"name\":\"HTTPS availability\",\"passed\":true,\"detail\":\"HTTPS used (encryption only, not proof of safety)\"},{\"name\":\"IP address instead of domain\",\"passed\":true,\"detail\":\"Uses a domain name\"},{\"name\":\"URL length\",\"passed\":true,\"detail\":\"40 characters\"},{\"name\":\"Suspicious symbols & characters\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Suspicious domain name\",\"passed\":true,\"detail\":\"Registered domain: microsoft.com\"},{\"name\":\"URL shortening service\",\"passed\":true,\"detail\":\"Not a known shortener\"},{\"name\":\"Suspicious keywords\",\"passed\":false,\"detail\":\"security\"},{\"name\":\"Domain impersonation\",\"passed\":true,\"detail\":\"No known brand imitation detected\"}],\"recommendations\":[\"No strong phishing indicators were found, but stay alert – new phishing sites appear every day.\",\"Only enter sensitive information on sites you reached by typing the official address.\",\"Remember: HTTPS only encrypts the connection. Phishing sites can also use HTTPS.\",\"Keep your browser and antivirus up to date and use a password manager (it won\'t auto-fill on fake domains).\"],\"disclaimer\":\"This result comes from transparent, rule-based automated analysis. It cannot guarantee that a website or email is safe or malicious. Always verify through official channels before sharing information.\",\"method\":\"Rule-based analysis (no AI / machine learning). The link was not opened.\"}', NOW() - INTERVAL 5 DAY - INTERVAL 16 HOUR),
  (2, 'https://tinyurl.com/free-gift-card', 30, 'SUSPICIOUS', '{\"normalizedUrl\":\"https://tinyurl.com/free-gift-card\",\"domain\":\"tinyurl.com\",\"registeredDomain\":\"tinyurl.com\",\"summary\":\"1 warning sign(s) were found, giving a risk score of 30/100.\",\"indicators\":[{\"id\":\"https_present\",\"category\":\"HTTPS\",\"points\":0,\"severity\":\"info\",\"title\":\"Uses HTTPS\",\"description\":\"The link uses HTTPS, so traffic is encrypted. However, HTTPS does NOT prove a website is legitimate – many phishing sites use free HTTPS certificates.\"},{\"id\":\"shortener\",\"category\":\"Redirection\",\"points\":30,\"severity\":\"high\",\"title\":\"URL shortening service\",\"description\":\"The link uses tinyurl.com, which hides the final destination. Phishers use shorteners to disguise malicious sites.\"}],\"checks\":[{\"name\":\"HTTPS availability\",\"passed\":true,\"detail\":\"HTTPS used (encryption only, not proof of safety)\"},{\"name\":\"IP address instead of domain\",\"passed\":true,\"detail\":\"Uses a domain name\"},{\"name\":\"URL length\",\"passed\":true,\"detail\":\"34 characters\"},{\"name\":\"Suspicious symbols & characters\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Suspicious domain name\",\"passed\":true,\"detail\":\"Registered domain: tinyurl.com\"},{\"name\":\"URL shortening service\",\"passed\":false,\"detail\":\"tinyurl.com\"},{\"name\":\"Suspicious keywords\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Domain impersonation\",\"passed\":true,\"detail\":\"No known brand imitation detected\"}],\"recommendations\":[\"Avoid entering passwords, card numbers, or personal details on this site.\",\"Visit the organisation\'s website by typing its official address yourself instead of clicking the link.\",\"Remember: HTTPS only encrypts the connection. Phishing sites can also use HTTPS.\",\"Use a link-expander service to preview where a shortened link really leads before clicking.\",\"Keep your browser and antivirus up to date and use a password manager (it won\'t auto-fill on fake domains).\"],\"disclaimer\":\"This result comes from transparent, rule-based automated analysis. It cannot guarantee that a website or email is safe or malicious. Always verify through official channels before sharing information.\",\"method\":\"Rule-based analysis (no AI / machine learning). The link was not opened.\"}', NOW() - INTERVAL 6 DAY - INTERVAL 19 HOUR);
INSERT INTO email_scans (user_id, risk_score, risk_level, scan_details, scanned_at) VALUES
  (2, 100, 'HIGH RISK', '{\"summary\":\"7 warning sign(s) were found, giving a risk score of 100/100.\",\"indicators\":[{\"id\":\"urgent_language\",\"category\":\"Language\",\"points\":25,\"severity\":\"high\",\"title\":\"Urgent or threatening language\",\"description\":\"The email pressures you to act quickly or threatens consequences. Creating panic is a classic social-engineering tactic.\",\"matches\":[\"urgent\",\"immediately\",\"within 24 hours\",\"will be suspended\",\"has been suspended\",\"unusual activity\",\"legal action\",\"failure to comply\"]},{\"id\":\"verification_request\",\"category\":\"Request\",\"points\":17,\"severity\":\"medium\",\"title\":\"Account verification request\",\"description\":\"The email asks you to verify, confirm, or update your account. Phishers use this to lead you to fake login pages.\",\"matches\":[\"verify your account\",\"click the link below\"]},{\"id\":\"sensitive_info\",\"category\":\"Request\",\"points\":24,\"severity\":\"medium\",\"title\":\"Requests for passwords or financial data\",\"description\":\"The email mentions passwords, PINs, card numbers or banking details. Legitimate organisations never ask for these by email.\",\"matches\":[\"password\",\"credit card\",\"card number\"]},{\"id\":\"suspicious_links\",\"category\":\"Links\",\"points\":25,\"severity\":\"high\",\"title\":\"High-risk link(s) found\",\"description\":\"At least one link in the email shows strong phishing indicators.\",\"matches\":[\"http://paypa1-secure.com/login/verify\"]},{\"id\":\"sender_impersonation\",\"category\":\"Sender\",\"points\":25,\"severity\":\"high\",\"title\":\"Sender domain imitates a brand\",\"description\":\"\\\"paypa1-support.com\\\" imitates \\\"paypal\\\" by swapping look-alike characters (such as 1 for l or 0 for o). The real site is paypal.com.\",\"matches\":[]},{\"id\":\"sender_mismatch\",\"category\":\"Sender\",\"points\":20,\"severity\":\"medium\",\"title\":\"Sender name does not match domain\",\"description\":\"The sender claims to be \\\"paypal\\\" but the email comes from \\\"paypa1-support.com\\\", which is not an official domain.\",\"matches\":[]},{\"id\":\"grammar\",\"category\":\"Language\",\"points\":13,\"severity\":\"medium\",\"title\":\"Grammar, spelling or style warnings\",\"description\":\"Spelling mistakes, generic greetings, ALL CAPS and excessive \\\"!\\\" are common in phishing emails. Real emails can have mistakes too, so this is a weak signal on its own.\",\"matches\":[\"generic greeting: \\\"dear customer\\\"\",\"3 exclamation marks\"]}],\"checks\":[{\"name\":\"Urgent / threatening language\",\"passed\":false,\"detail\":\"8 phrase(s)\"},{\"name\":\"Account verification requests\",\"passed\":false,\"detail\":\"2 phrase(s)\"},{\"name\":\"Password / banking requests\",\"passed\":false,\"detail\":\"3 term(s)\"},{\"name\":\"Suspicious links\",\"passed\":false,\"detail\":\"1 link(s), 1 flagged\"},{\"name\":\"Sender information\",\"passed\":false,\"detail\":\"2 issue(s) with sender\"},{\"name\":\"Prize / lottery scam\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Grammar & spelling indicators\",\"passed\":false,\"detail\":\"2 warning(s)\"}],\"links\":[{\"url\":\"http://paypa1-secure.com/login/verify\",\"riskScore\":68,\"riskLevel\":\"HIGH RISK\"}],\"recommendations\":[\"Do NOT click any links, open attachments, or reply to this email.\",\"Never send passwords, PINs, OTP codes, or card details by email – real organisations will not ask for them.\",\"Report the email as phishing (e.g. \\\"Report phishing\\\" in Gmail/Outlook) and delete it.\",\"If you already shared a password or code, change it immediately and enable two-factor authentication.\",\"Urgency is a pressure tactic. Take your time – legitimate deadlines can be confirmed independently.\",\"Hover over links to see the real address before clicking, and check them with the CyberGuard URL scanner.\"],\"disclaimer\":\"This result comes from transparent, rule-based automated analysis. It cannot guarantee that a website or email is safe or malicious. Always verify through official channels before sharing information.\",\"method\":\"Rule-based analysis (no AI / machine learning). Links were not opened.\",\"meta\":{\"excerpt\":\"URGENT: Your account has been suspended – Dear Customer, We detected unusual activity on your account. Your account will be suspended within 24 hours unless you\",\"senderDomain\":\"paypa1-support.com\",\"wordCount\":44,\"linkCount\":1}}', NOW() - INTERVAL 0 DAY - INTERVAL 1 HOUR),
  (3, 75, 'HIGH RISK', '{\"summary\":\"5 warning sign(s) were found, giving a risk score of 75/100.\",\"indicators\":[{\"id\":\"urgent_language\",\"category\":\"Language\",\"points\":8,\"severity\":\"low\",\"title\":\"Urgent or threatening language\",\"description\":\"The email pressures you to act quickly or threatens consequences. Creating panic is a classic social-engineering tactic.\",\"matches\":[\"within 48 hours\"]},{\"id\":\"sensitive_info\",\"category\":\"Request\",\"points\":12,\"severity\":\"medium\",\"title\":\"Requests for passwords or financial data\",\"description\":\"The email mentions passwords, PINs, card numbers or banking details. Legitimate organisations never ask for these by email.\",\"matches\":[\"bank account\"]},{\"id\":\"prize_scam\",\"category\":\"Scam\",\"points\":35,\"severity\":\"high\",\"title\":\"Prize, lottery or money scam\",\"description\":\"The email promises prizes, winnings, inheritance or easy money. These are almost always advance-fee scams.\",\"matches\":[\"you have won\",\"lottery\",\"prize\",\"claim your prize\",\"million dollars\",\"processing fee\"]},{\"id\":\"grammar\",\"category\":\"Language\",\"points\":5,\"severity\":\"low\",\"title\":\"Grammar, spelling or style warnings\",\"description\":\"Spelling mistakes, generic greetings, ALL CAPS and excessive \\\"!\\\" are common in phishing emails. Real emails can have mistakes too, so this is a weak signal on its own.\",\"matches\":[\"3 exclamation marks\"]},{\"id\":\"advance_fee\",\"category\":\"Scam\",\"points\":15,\"severity\":\"medium\",\"title\":\"Advance-fee fraud pattern\",\"description\":\"The email combines a prize or money offer with a request for payment or financial details – the typical pattern of advance-fee fraud.\",\"matches\":[]}],\"checks\":[{\"name\":\"Urgent / threatening language\",\"passed\":false,\"detail\":\"1 phrase(s)\"},{\"name\":\"Account verification requests\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Password / banking requests\",\"passed\":false,\"detail\":\"1 term(s)\"},{\"name\":\"Suspicious links\",\"passed\":true,\"detail\":\"No links found\"},{\"name\":\"Sender information\",\"passed\":true,\"detail\":\"gmail.com – no issues found\"},{\"name\":\"Prize / lottery scam\",\"passed\":false,\"detail\":\"6 phrase(s)\"},{\"name\":\"Grammar & spelling indicators\",\"passed\":false,\"detail\":\"1 warning(s)\"}],\"links\":[],\"recommendations\":[\"Do NOT click any links, open attachments, or reply to this email.\",\"Never send passwords, PINs, OTP codes, or card details by email – real organisations will not ask for them.\",\"Report the email as phishing (e.g. \\\"Report phishing\\\" in Gmail/Outlook) and delete it.\",\"If you already shared a password or code, change it immediately and enable two-factor authentication.\",\"You cannot win a lottery or prize you never entered. Never pay a \\\"fee\\\" to receive winnings.\",\"Urgency is a pressure tactic. Take your time – legitimate deadlines can be confirmed independently.\"],\"disclaimer\":\"This result comes from transparent, rule-based automated analysis. It cannot guarantee that a website or email is safe or malicious. Always verify through official channels before sharing information.\",\"method\":\"Rule-based analysis (no AI / machine learning). Links were not opened.\",\"meta\":{\"excerpt\":\"CONGRATULATIONS WINNER – CONGRATULATIONS!!! You have won the international lottery of 2 million dollars. To claim your prize send your bank account details and \",\"senderDomain\":\"gmail.com\",\"wordCount\":32,\"linkCount\":0}}', NOW() - INTERVAL 2 DAY - INTERVAL 2 HOUR),
  (3, 0, 'SAFE', '{\"summary\":\"No phishing indicators were triggered by our rules.\",\"indicators\":[],\"checks\":[{\"name\":\"Urgent / threatening language\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Account verification requests\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Password / banking requests\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Suspicious links\",\"passed\":true,\"detail\":\"No links found\"},{\"name\":\"Sender information\",\"passed\":true,\"detail\":\"university.edu.pk – no issues found\"},{\"name\":\"Prize / lottery scam\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Grammar & spelling indicators\",\"passed\":true,\"detail\":\"None found\"}],\"links\":[],\"recommendations\":[\"No strong phishing indicators were found, but always double-check unexpected requests.\"],\"disclaimer\":\"This result comes from transparent, rule-based automated analysis. It cannot guarantee that a website or email is safe or malicious. Always verify through official channels before sharing information.\",\"method\":\"Rule-based analysis (no AI / machine learning). Links were not opened.\",\"meta\":{\"excerpt\":\"Meeting notes – Hi Sara, attached are the meeting notes from Tuesday. Let me know if anything is missing. The project review is next week in room 204. Thanks, A\",\"senderDomain\":\"university.edu.pk\",\"wordCount\":27,\"linkCount\":0}}', NOW() - INTERVAL 4 DAY - INTERVAL 3 HOUR),
  (2, 40, 'SUSPICIOUS', '{\"summary\":\"3 warning sign(s) were found, giving a risk score of 40/100.\",\"indicators\":[{\"id\":\"verification_request\",\"category\":\"Request\",\"points\":12,\"severity\":\"medium\",\"title\":\"Account verification request\",\"description\":\"The email asks you to verify, confirm, or update your account. Phishers use this to lead you to fake login pages.\",\"matches\":[\"update your account\"]},{\"id\":\"suspicious_links\",\"category\":\"Links\",\"points\":15,\"severity\":\"medium\",\"title\":\"Suspicious link(s) found\",\"description\":\"At least one link in the email has warning signs.\",\"matches\":[\"https://bit.ly/mailbox-upgrade\"]},{\"id\":\"grammar\",\"category\":\"Language\",\"points\":13,\"severity\":\"medium\",\"title\":\"Grammar, spelling or style warnings\",\"description\":\"Spelling mistakes, generic greetings, ALL CAPS and excessive \\\"!\\\" are common in phishing emails. Real emails can have mistakes too, so this is a weak signal on its own.\",\"matches\":[\"misspelling: \\\"recieve\\\"\",\"generic greeting: \\\"dear user\\\"\"]}],\"checks\":[{\"name\":\"Urgent / threatening language\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Account verification requests\",\"passed\":false,\"detail\":\"1 phrase(s)\"},{\"name\":\"Password / banking requests\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Suspicious links\",\"passed\":false,\"detail\":\"1 link(s), 1 flagged\"},{\"name\":\"Sender information\",\"passed\":true,\"detail\":\"uni-mail-support.info – no issues found\"},{\"name\":\"Prize / lottery scam\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Grammar & spelling indicators\",\"passed\":false,\"detail\":\"2 warning(s)\"}],\"links\":[{\"url\":\"https://bit.ly/mailbox-upgrade\",\"riskScore\":30,\"riskLevel\":\"SUSPICIOUS\"}],\"recommendations\":[\"Be careful: verify the request by contacting the organisation using a phone number or website you already trust.\",\"Do not click links in the email – type the official website address yourself.\",\"Hover over links to see the real address before clicking, and check them with the CyberGuard URL scanner.\"],\"disclaimer\":\"This result comes from transparent, rule-based automated analysis. It cannot guarantee that a website or email is safe or malicious. Always verify through official channels before sharing information.\",\"method\":\"Rule-based analysis (no AI / machine learning). Links were not opened.\",\"meta\":{\"excerpt\":\"Mailbox storage full – Dear user, your mailbox is almost full and you will not recieve new messages. Kindly update your account details using this link to incre\",\"senderDomain\":\"uni-mail-support.info\",\"wordCount\":26,\"linkCount\":1}}', NOW() - INTERVAL 6 DAY - INTERVAL 4 HOUR),
  (2, 0, 'SAFE', '{\"summary\":\"No phishing indicators were triggered by our rules.\",\"indicators\":[],\"checks\":[{\"name\":\"Urgent / threatening language\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Account verification requests\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Password / banking requests\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Suspicious links\",\"passed\":true,\"detail\":\"No links found\"},{\"name\":\"Sender information\",\"passed\":true,\"detail\":\"netflix.com – no issues found\"},{\"name\":\"Prize / lottery scam\",\"passed\":true,\"detail\":\"None found\"},{\"name\":\"Grammar & spelling indicators\",\"passed\":true,\"detail\":\"None found\"}],\"links\":[],\"recommendations\":[\"No strong phishing indicators were found, but always double-check unexpected requests.\"],\"disclaimer\":\"This result comes from transparent, rule-based automated analysis. It cannot guarantee that a website or email is safe or malicious. Always verify through official channels before sharing information.\",\"method\":\"Rule-based analysis (no AI / machine learning). Links were not opened.\",\"meta\":{\"excerpt\":\"Your monthly receipt – Hi Ali, thanks for being a member. Your monthly plan was renewed today. You can view your plan and billing at any time from your account \",\"senderDomain\":\"netflix.com\",\"wordCount\":30,\"linkCount\":0}}', NOW() - INTERVAL 1 DAY - INTERVAL 5 HOUR);
